 1→import { test, expect } from '@playwright/test';
 2→import * as path from 'path';
 3→import { loadAllScenarios } from '../lib/yaml-loader';
 4→import { executeStep } from '../lib/actions';
 5→import { runStructuralVerify } from '../lib/verifiers';
 6→import { runLlmJudge } from '../lib/llm-judge';
 7→import type { VerifyStep, VerifyLlmStep } from '../lib/types';
 8→
 9→const scenariosDir = path.resolve(__dirname, '..', 'scenarios');
10→
11→let scenarioFiles: ReturnType<typeof loadAllScenarios>;
12→try {
13→  scenarioFiles = loadAllScenarios(scenariosDir);
14→} catch (e) {
15→  // No scenario files — skip gracefully
16→  scenarioFiles = [];
17→}
18→
19→for (const { file, data } of scenarioFiles) {
20→  test.describe(file, () => {
21→    for (const scenario of data.scenarios) {
22→      test(scenario.name, async ({ page }) => {
23→        // Navigate to base URL
24→        await page.goto('/');
25→        await page.waitForLoadState('networkidle');
26→
27→        for (let i = 0; i < scenario.steps.length; i++) {
28→          const step = scenario.steps[i];
29→          const stepLabel = `Step ${i + 1} [${step.action}]`;
30→
31→          await test.step(stepLabel, async () => {
32→            if (step.action === 'verify') {
33→              await runStructuralVerify(page, step as VerifyStep);
34→            } else if (step.action === 'verify_llm') {
35→              const llmStep = step as VerifyLlmStep;
36→              const lastAssistant = page.locator('.message-bubble--assistant').last();
37→              const pageContent = await lastAssistant.innerText();
38→              const result = await runLlmJudge(pageContent, llmStep);
39→
40→              expect(
41→                result.pass,
42→                `LLM judge failed (score: ${result.score}): ${result.reasoning}`
43→              ).toBe(true);
44→            } else {
45→              await executeStep(page, step, scenariosDir);
46→            }
47→          });
48→        }
49→      });
50→    }
51→  });
52→}
53→

