async function handleDialog(page: Page, accept: boolean): Promise<void> {
  // Set up dialog handler before the action that triggers it.
  // Since confirm_dialog is called AFTER the click that triggers the dialog,
  // we need to handle the case where the dialog may already be pending.
  // Playwright auto-dismisses dialogs, so we set up a one-time listener.
  page.once('dialog', async (dialog) => {
    if (accept) {
      await dialog.accept();
    } else {
      await dialog.dismiss();
    }
  });
}

